export class Order {
  #items = [];
  #status = 'new';
  addItem(item) {
    if (this.#status !== 'new') throw new Error('order closed');
    this.#items.push(item);
  }
  pay() { this.#status = 'paid'; }
  get status() { return this.#status; }
}

