// order.js - the module is the contour
export function createOrder() {
  const items = [];
  let status = 'new';                     // private to the closure
  return {
    addItem(item) { if (status !== 'new') throw new Error('closed'); items.push(item); },
    pay() { status = 'paid'; },
    get status() { return status; },
  };
}
